const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const offKey='zhufeng-analytics-off',visitorKey='zhufeng-anonymous-browser-v1';
const consentKey='zhufeng-analytics-consent-v1';
export function analyticsConsent(storage,now=Date.now()){
  try{const x=JSON.parse(storage.getItem(consentKey)||'null');return x?.version===1&&typeof x.allowed==='boolean'&&Number.isFinite(x.at)&&now>=x.at&&now-x.at<30*86400000?x.allowed:null;}catch{return null;}
}
export function setAnalyticsConsent(storage,allowed,now=Date.now()){
  if(typeof allowed!=='boolean')throw Error('统计选择无效');
  storage.setItem(consentKey,JSON.stringify({version:1,allowed,at:now}));
  if(!allowed)storage.removeItem(visitorKey);
}
export function trafficRoute(hash){const path=hash.replace(/^#\/?/,'')||'checkup';if(/^checkup\/model\/[a-z0-9-]+\/(low|medium|high)$/.test(path))return trafficRoute('#'+path.split('/').slice(0,3).join('/'));if(path.startsWith('checkup/compare/'))return 'checkup/compare';if(path==='checkup/play')return 'checkup/works';if(/^checkup\/works(?:\/(?:visual|zebra)(?:\/(?:deepseek-v41-flash|kimi-k31-pro|kimi-k3|glm53-flash|minimax-m31-flash|claude-sonnet55|claude-haiku55|gpt6-luna|gemini38-flash|mistral-large4))?)?$/.test(path))return 'checkup/works';return /^checkup(?:\/(?:compare|results|repairs|purpose|reasoning|edit|memory|honesty|visual|receipt|zebra|efforts|history|how|contact|model\/(?:deepseek-v41-flash|kimi-k31-pro|kimi-k3|glm53-flash|minimax-m31-flash|claude-sonnet55|claude-haiku55|gpt6-luna|gemini38-flash|mistral-large4)))?$/.test(path)?path:null;}
export function referrerGroup(referrer,origin){try{const u=new URL(referrer);if(u.origin===origin)return 'internal';const h=u.hostname;if(/(^|\.)(x\.com|twitter\.com|t\.co)$/.test(h))return 'x.com';if(/(^|\.)google\.[a-z.]+$/.test(h))return 'google';if(/(^|\.)bing\.com$/.test(h))return 'bing';return 'other';}catch{return 'direct';}}
export function analyticsDisabled(storage,nav,host){try{return analyticsConsent(storage)!==true||['localhost','127.0.0.1','[::1]'].includes(host)||nav.doNotTrack==='1'||nav.globalPrivacyControl===true||nav.webdriver===true||storage.getItem(offKey)==='1';}catch{return true;}}
export function browserIdentity(storage,now=Date.now(),makeId=()=>crypto.randomUUID()){
  try{const old=JSON.parse(storage.getItem(visitorKey)||'null');if(old&&now-old.createdAt<30*86400000&&now>=old.createdAt&&/^[\da-f-]{36}$/i.test(old.id))return old.id;}catch{}
  const item={id:makeId(),createdAt:now};storage.setItem(visitorKey,JSON.stringify(item));return item.id;
}
export function startTraffic(){
  let last=null;
  const record=async()=>{try{if(analyticsDisabled(localStorage,navigator,location.hostname)||document.visibilityState!=='visible')return;const route=trafficRoute(location.hash);if(!route){last=null;return;}if(route===last)return;last=route;const visitorId=browserIdentity(localStorage);await fetch('/api/traffic',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({kind:'pageview',eventId:crypto.randomUUID(),visitorId,route,source:referrerGroup(document.referrer,location.origin),device:innerWidth<768?'mobile':innerWidth<1100?'tablet':'desktop'}),keepalive:true});}catch{/* Analytics must never interrupt the site. */}};
  addEventListener('hashchange',record);addEventListener('analyticsconsentchange',()=>{last=null;record();});document.addEventListener('visibilitychange',record);record();
}
const routeName=path=>({'checkup':'首页','checkup/results':'模型测评','checkup/works':'整活作品','checkup/repairs':'翻车修复','checkup/compare':'模型对比','checkup/play':'整活作品（原入口）','checkup/receipt':'账单识别','checkup/zebra':'斑马绘画','checkup/efforts':'三档成绩','checkup/history':'历史默认档','checkup/purpose':'理解目的','checkup/reasoning':'推理纠错','checkup/edit':'只改指定字','checkup/memory':'多轮记忆','checkup/honesty':'不编信息','checkup/visual':'画图连接','checkup/how':'测试方法','checkup/contact':'关于与联系'}[path]||'模型答卷');
export function validateTrafficSummary(x){
  const count=n=>Number.isSafeInteger(n)&&n>=0;
  if(x?.schemaVersion!=='traffic-summary-v1'||!['live','preview'].includes(x.state)||![7,30].includes(x.days)||!/^\d{4}-\d\d-\d\d$/.test(x.since)||!/^\d{4}-\d\d-\d\d$/.test(x.through)||!Number.isFinite(Date.parse(x.generatedAt))||x.startedOn!==null&&!/^\d{4}-\d\d-\d\d$/.test(x.startedOn)||![x.total,x.today].every(n=>n&&count(n.pv)&&count(n.uv)&&n.uv<=n.pv))throw Error('统计格式不完整');
  for(const key of ['daily','pages','sources','devices'])if(!Array.isArray(x[key])||x[key].length>100||x[key].some(r=>key==='daily'?!/^\d{4}-\d\d-\d\d$/.test(r.day)||!count(r.pv)||!count(r.uv):typeof r.label!=='string'||r.label.length>150||!count(r.count)))throw Error('统计明细不完整');
  return x;
}
const bars=(items,name)=>items.length?items.map(r=>`<div class="traffic-bar-row"><span>${e(name(r.label))}</span><div><i style="width:${Math.max(1,r.count/Math.max(...items.map(x=>x.count))*100)}%"></i></div><strong>${r.count}</strong></div>`).join(''):'<p class="evidence-meta">暂无有效访问记录。</p>';
export function audienceView(data,{days=30,error='',excluded=false}={}){
  const controls=`<div class="audience-controls"><label>统计周期 <select data-traffic-days aria-label="统计周期"><option value="7" ${days===7?'selected':''}>最近7天</option><option value="30" ${days===30?'selected':''}>最近30天</option></select></label><button data-traffic-refresh>刷新数据 ↻</button></div>`;
  let content=error?`<p class="checkup-warning">${e(error)}。尚未读到的指标显示为“—”，不会用0代替。</p>`:!data?'<p>正在读取服务端统计…</p>':'';
  content+=`<div class="traffic-stats">${[['去重浏览器 UV',data?.total?.uv],['浏览量 PV',data?.total?.pv],['今日浏览器 UV',data?.today?.uv],['今日浏览量 PV',data?.today?.pv]].map(([label,n])=>`<div><span>${label}</span><strong>${n??'—'}</strong></div>`).join('')}</div>`;
  if(data){const daily=new Map(data.daily.map(r=>[r.day,r])),daysList=Array.from({length:data.days},(_,i)=>new Date(Date.parse(data.since+'T00:00:00Z')+i*86400000).toISOString().slice(0,10)),peak=Math.max(1,...data.daily.map(x=>x.pv));content+=`${data.state==='preview'?'<p class="checkup-warning">本机离线验收环境，不是线上访客数据。</p>':''}<p class="evidence-meta">${e(data.since)} — ${e(data.through)} · UTC+8 · 首次有效记录：${e(data.startedOn||'尚无')} · 更新：${e(new Date(data.generatedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}))}</p><section class="traffic-panel"><h2>每日浏览量</h2><div class="traffic-trend" role="img" aria-label="每日浏览量趋势，明细见下方展开表">${daysList.map(day=>{const before=!data.startedOn||day<data.startedOn,n=daily.get(day)?.pv||0;return `<div title="${day}：${before?'尚未采集':n+'次浏览'}" class="${before?'before-start':''}"><i style="height:${before?2:Math.max(2,n/peak*100)}%"></i><span>${day.slice(5)}</span></div>`;}).join('')}</div><details><summary>查看每日 PV / UV 明细</summary><table><thead><tr><th>日期</th><th>PV</th><th>UV</th></tr></thead><tbody>${daysList.map(day=>`<tr><td>${day}</td><td>${!data.startedOn||day<data.startedOn?'未采集':daily.get(day)?.pv||0}</td><td>${!data.startedOn||day<data.startedOn?'未采集':daily.get(day)?.uv||0}</td></tr>`).join('')}</tbody></table></details></section><div class="traffic-columns"><section class="traffic-panel"><h2>访问来源</h2>${bars(data.sources,k=>({direct:'直接访问 / 来源未提供',internal:'站内跳转','x.com':'X / Twitter',google:'Google',bing:'Bing',other:'其他站外来源'}[k]||k))}</section><section class="traffic-panel"><h2>访问设备</h2>${bars(data.devices,k=>({desktop:'桌面',tablet:'平板',mobile:'手机'}[k]||k))}</section></div><section class="traffic-panel"><h2>热门页面</h2>${bars(data.pages,routeName)}</section>`;}
  return `<div class="page-head"><div><div class="eyebrow">逐风 / AUDIENCE</div><h1>访客报告</h1><p class="subtitle">供合作方查看的真实流量概览。数据从启用统计后积累，不补写历史数字。</p></div>${controls}</div>${content}<section class="traffic-panel traffic-method"><h2>这些数字代表什么？</h2><p>本站自建访问分析须由访客主动允许；拒绝或关闭不影响浏览。因此这些数字不覆盖所有访客。UV 按30天有效的随机浏览器标识去重，是浏览器数量估算，不等同于真实人数。同一人换设备会重复计数；禁用存储、隐私选项或拦截脚本会漏计。周期 UV 单独去重，不是每日 UV 相加。</p><p>PV 统计可见页面的打开及题目、模型之间的切换。访客报告、自测工具、本机预览、常见机器人和验收事件不计入。来源仅保留分类；本统计不保存 IP、账号、邮箱、完整来源网址或输入内容。访问统计接口时清理90天前的明细。</p><p>访问范围由站点分享设置决定。若站点仅自己可见，外部广告主无法打开，内部浏览也不能作为公开受众规模。本站数据尚未经第三方审计；不推断年龄、性别、收入或购买意向。</p><button data-traffic-exclude>${excluded?'恢复本机访问统计':'排除本机访问'}</button><span class="evidence-meta"> ${excluded?'本浏览器已排除':'可排除站长自己的日常访问'}；浏览器的 DNT / GPC 隐私偏好始终优先。</span></section>`;
}
export function createAudienceController({main,rerender}){
  let data=null,error='',days=30,loading=false,seq=0;const active=()=>location.hash==='#checkup/audience';
  const excluded=()=>{try{return localStorage.getItem(offKey)==='1';}catch{return true;}};
  async function load(){loading=true;const id=++seq;try{const r=await fetch('/api/traffic?days='+days,{cache:'no-store'});if(!r.ok)throw Error('服务端统计暂不可用');const next=validateTrafficSummary(await r.json());if(id!==seq)return;data=next;error='';}catch(err){if(id!==seq)return;data=null;error=err.message;}loading=false;if(active())rerender();}
  main.addEventListener('change',ev=>{if(active()&&ev.target.hasAttribute('data-traffic-days')){days=Number(ev.target.value);data=null;error='';load();rerender();}});
  main.addEventListener('click',ev=>{if(!active())return;const b=ev.target.closest('button');if(b?.hasAttribute('data-traffic-refresh')){error='';load();}if(b?.hasAttribute('data-traffic-exclude')){try{localStorage.setItem(offKey,excluded()?'0':'1');}catch{error='浏览器未允许保存排除选项';}rerender();}});
  return {render(){if(!data&&!error&&!loading)load();return audienceView(data,{days,error,excluded:excluded()});}};
}
